INSERT INTO `disenos_ticket` VALUES (1,'{\"ticket\": {\"ancho\": 80, \"logoUrl\": \"\", \"direccion\": \"3 calle oriente, Barrio Las Flores, Ahuachapán local número dos, situado, Ahuachapán\", \"politicas\": [\"Para retirar las prendas, es indispensable presentar este recibo como único comprobante válido.\", \"Las prendas deberán ser retiradas en un máximo de 1 día; de no hacerlo, se aplicará un cargo adicional de $0.50 por cada día de retraso.\", \"El plazo para realizar cualquier reclamación sobre el servicio es de 2 días hábiles después de la entrega.\", \"La lavandería no se responsabiliza por pérdidas o daños causados por eventos fortuitos o fuerza mayor, como robos, incendios o desastres naturales, siendo este riesgo asumido por el cliente.\", \"Las prendas no retiradas en un plazo de 30 días serán consideradas abandonadas, liberando a la lavandería de toda responsabilidad sobre ellas.\", \"Si dichas prendas no son reclamadas en un plazo adicional de 10 días (40 días en total desde su disponibilidad), la lavandería se reserva el derecho de donarlas a refugios u organizaciones benéficas sin posibilidad de reclamos futuros.\"], \"instruccion\": \"Presente este ticket al retirar sus prendas.\", \"mostrarLogo\": true, \"mostrarPago\": true, \"promocionId\": \"\", \"mensajeFinal\": \"¡Gracias por su preferencia!\", \"mostrarFirma\": true, \"tamanoFuente\": 12, \"mostrarCorreo\": true, \"mostrarEntrega\": true, \"mostrarPrecios\": true, \"promocionValor\": 0, \"textoPromocion\": \"¡Aprovecha esta promoción en tu próxima visita!\", \"mostrarDetalles\": true, \"mostrarTelefono\": true, \"promocionNombre\": \"\", \"textoAceptacion\": \"Al firmar usted acepta nuestras condiciones y políticas del servicio.\", \"contactoPolitica\": \"Dudas: lavanderiasalinassv@gmail.com · WhatsApp 2497 6699\", \"mostrarDireccion\": true, \"mostrarPoliticas\": true, \"mostrarPromocion\": false, \"mostrarServicios\": true, \"promocionFechaFin\": \"\", \"promocionDescripcion\": \"\", \"promocionTipoDescuento\": \"porcentaje\"}, \"prendas\": {\"ancho\": 58, \"logoUrl\": \"\", \"direccion\": \"3 calle oriente, Barrio Las Flores, Ahuachapán local número dos, situado, Ahuachapán\", \"politicas\": [\"Para retirar las prendas, es indispensable presentar este recibo como único comprobante válido.\", \"Las prendas deberán ser retiradas en un máximo de 1 día; de no hacerlo, se aplicará un cargo adicional de $0.50 por cada día de retraso.\", \"El plazo para realizar cualquier reclamación sobre el servicio es de 2 días hábiles después de la entrega.\", \"La lavandería no se responsabiliza por pérdidas o daños causados por eventos fortuitos o fuerza mayor, como robos, incendios o desastres naturales, siendo este riesgo asumido por el cliente.\", \"Las prendas no retiradas en un plazo de 30 días serán consideradas abandonadas, liberando a la lavandería de toda responsabilidad sobre ellas.\", \"Si dichas prendas no son reclamadas en un plazo adicional de 10 días (40 días en total desde su disponibilidad), la lavandería se reserva el derecho de donarlas a refugios u organizaciones benéficas sin posibilidad de reclamos futuros.\"], \"instruccion\": \"\", \"mostrarLogo\": true, \"mostrarPago\": false, \"promocionId\": \"\", \"mensajeFinal\": \"\", \"mostrarFirma\": false, \"tamanoFuente\": 11, \"mostrarCorreo\": false, \"mostrarEntrega\": true, \"mostrarPrecios\": false, \"promocionValor\": 0, \"textoPromocion\": \"¡Aprovecha esta promoción en tu próxima visita!\", \"mostrarDetalles\": true, \"mostrarTelefono\": true, \"promocionNombre\": \"\", \"textoAceptacion\": \"Al firmar usted acepta nuestras condiciones y políticas del servicio.\", \"contactoPolitica\": \"Dudas: lavanderiasalinassv@gmail.com · WhatsApp 2497 6699\", \"mostrarDireccion\": true, \"mostrarPoliticas\": false, \"mostrarPromocion\": false, \"mostrarServicios\": false, \"promocionFechaFin\": \"\", \"promocionDescripcion\": \"\", \"promocionTipoDescuento\": \"porcentaje\"}}','2026-10-09 15:56:27');

