INSERT INTO `guia_configuracion` VALUES ('articulos_adicionales_v10','completado'),('articulos_adicionales_v11','completado'),('articulos_adicionales_v12','completado'),('articulos_adicionales_v2','completado'),('articulos_adicionales_v3','completado'),('articulos_adicionales_v4','completado'),('articulos_adicionales_v5','completado'),('articulos_adicionales_v6','completado'),('articulos_adicionales_v7','completado'),('articulos_adicionales_v8','completado'),('articulos_adicionales_v9','completado'),('articulos_iniciales_v1','completado');

CREATE TABLE `horarios_config` (
  `id` tinyint NOT NULL DEFAULT '1',
