  `creado_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_movimientos_caja_turno` (`turno_id`),
  KEY `idx_movimientos_caja_tipo` (`tipo`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `notificaciones` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipo` enum('aviso','problema') COLLATE utf8mb4_unicode_ci NOT NULL,
  `destinatario_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `destinatario_rol` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `autor_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `autor_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titulo` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mensaje` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `tema` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detalles` text COLLATE utf8mb4_unicode_ci,
  `estado` enum('pendiente','en_proceso','resuelto') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `leida` tinyint(1) NOT NULL DEFAULT '0',
  `fecha_resolucion` datetime DEFAULT NULL,
  `creada_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `imagen_url` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_notificaciones_destinatario` (`destinatario_id`,`leida`,`creada_at`),
  KEY `idx_notificaciones_tipo_estado` (`tipo`,`estado`,`creada_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `notificaciones_lecturas` (
  `notificacion_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_usuario` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `leida` tinyint(1) NOT NULL DEFAULT '1',
  `leida_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`notificacion_id`,`usuario_id`),
  KEY `idx_notificaciones_lecturas_usuario` (`usuario_id`,`leida`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `orden_anticipos` (
  `id` char(36) NOT NULL,
  `orden_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `turno_id` varchar(64) DEFAULT NULL,
  `monto` decimal(10,2) NOT NULL,
  `fecha` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_anticipos_orden` (`orden_id`),
  CONSTRAINT `fk_anticipos_orden` FOREIGN KEY (`orden_id`) REFERENCES `ordenes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `orden_cargos_extra` (
  `id` char(36) NOT NULL,
  `orden_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` varchar(200) NOT NULL,
  `monto` decimal(10,2) NOT NULL,
  `fecha` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cargos_orden` (`orden_id`),
  CONSTRAINT `fk_cargos_orden` FOREIGN KEY (`orden_id`) REFERENCES `ordenes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `orden_fotos` (
  `id` char(36) NOT NULL,
  `orden_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `posicion` int NOT NULL DEFAULT '0',
  `url` longtext NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_fotos_orden` (`orden_id`),
  CONSTRAINT `fk_fotos_orden` FOREIGN KEY (`orden_id`) REFERENCES `ordenes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `orden_item_insumos` (
  `id` char(36) NOT NULL,
  `orden_item_id` char(36) NOT NULL,
  `producto_id` varchar(36) NOT NULL,
  `cantidad` decimal(10,3) NOT NULL DEFAULT '0.000',
  PRIMARY KEY (`id`),
  KEY `idx_insumos_item` (`orden_item_id`),
  CONSTRAINT `fk_insumos_item` FOREIGN KEY (`orden_item_id`) REFERENCES `orden_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `orden_items` (
  `id` char(36) NOT NULL,
  `orden_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `producto_id` varchar(36) NOT NULL,
  `nombre` varchar(150) NOT NULL,
  `precio` decimal(10,2) NOT NULL DEFAULT '0.00',
  `unidad` varchar(20) NOT NULL DEFAULT 'otro',
  `cantidad` decimal(10,2) NOT NULL DEFAULT '1.00',
  `nota` text,
  PRIMARY KEY (`id`),
  KEY `idx_orden_items_orden` (`orden_id`),
  KEY `idx_orden_items_producto` (`producto_id`),
  CONSTRAINT `fk_orden_items_orden` FOREIGN KEY (`orden_id`) REFERENCES `ordenes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `orden_movimientos` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orden_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `texto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `usuario_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario_nombre` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_movs_orden` (`orden_id`),
  KEY `idx_orden_movimientos_usuario` (`usuario_id`),
  CONSTRAINT `fk_movs_orden` FOREIGN KEY (`orden_id`) REFERENCES `ordenes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `orden_movimientos_archivados` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orden_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `secuencia` int DEFAULT NULL,
  `texto` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_movs_archivados_numero` (`secuencia`),
  KEY `idx_movs_archivados_fecha` (`fecha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ordenes` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `secuencia` int NOT NULL AUTO_INCREMENT,
  `estado` enum('pendiente','en_proceso','listo','entregado','cerrada','cancelada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `turno_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `nombre_cliente` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_pais` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '+503',
  `telefono` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `guardar_directorio` tinyint(1) NOT NULL DEFAULT '0',
  `envio_domicilio` tinyint(1) NOT NULL DEFAULT '0',
  `direccion_entrega` mediumtext COLLATE utf8mb4_unicode_ci,
  `fecha_entrega_activa` tinyint(1) NOT NULL DEFAULT '0',
  `mora_activa` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_entrega` date DEFAULT NULL,
  `hora_entrega` time DEFAULT NULL,
  `mora_dias_cobrados` int NOT NULL DEFAULT '0',
  `mora_detenida_at` datetime DEFAULT NULL,
  `mora_pausa_segundos` int NOT NULL DEFAULT '0',
  `entregado_at` datetime DEFAULT NULL,
  `estado_pago` enum('porCobrar','anticipo','pagado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'porCobrar',
  `metodo_pago` enum('efectivo','tarjeta','transferencia') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'efectivo',
  `monto_recibido` decimal(10,2) NOT NULL DEFAULT '0.00',
  `descuento` decimal(5,2) NOT NULL DEFAULT '0.00',
  `descuento_manual` decimal(5,2) NOT NULL DEFAULT '0.00',
  `descuento_promocion` decimal(5,2) NOT NULL DEFAULT '0.00',
  `subtotal` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cambio` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cantidad_prendas` int NOT NULL DEFAULT '0' COMMENT 'Cantidad de prendas recibidas',
  `detalles_prendas` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'Notas sobre las prendas recibidas',
  `nota_interna` mediumtext COLLATE utf8mb4_unicode_ci,
  `motivo_cancelacion` mediumtext COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `tarjeta_monto` decimal(12,2) DEFAULT NULL COMMENT 'Monto pagado con tarjeta',
  `tarjeta_referencia` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Número de referencia del POS',
  `transferencia_monto` decimal(12,2) DEFAULT NULL COMMENT 'Monto pagado por transferencia',
  `transferencia_comprobante` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'URL del comprobante de transferencia',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ordenes_secuencia` (`secuencia`),
  KEY `idx_ordenes_turno` (`turno_id`),
  KEY `idx_ordenes_telefono` (`telefono`),
  KEY `idx_ordenes_estado` (`estado`),
  KEY `idx_ordenes_tarjeta_referencia` (`tarjeta_referencia`)
) ENGINE=InnoDB AUTO_INCREMENT=416 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ordenes_eliminadas_auditoria` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orden_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `secuencia` int DEFAULT NULL,
  `usuario_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha` datetime NOT NULL,
  `orden_json` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_ordenes_eliminadas_fecha` (`fecha`),
  KEY `idx_ordenes_eliminadas_usuario` (`usuario_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promocion_usos_qr` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `promocion_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orden_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cliente_telefono` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_promocion_usos_qr_orden` (`orden_id`),
  KEY `idx_promocion_usos_qr_cliente` (`promocion_id`,`cliente_telefono`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promociones` (
  `id` char(36) NOT NULL,
  `nombre` varchar(150) NOT NULL,
  `descripcion` text,
  `tipo_descuento` enum('porcentaje','dinero') NOT NULL,
  `valor` decimal(10,2) NOT NULL,
  `tipo_cliente_aplica` enum('todos','registrados','recurrentes') NOT NULL DEFAULT 'todos',
  `min_ordenes` int DEFAULT NULL,
  `vigente` tinyint(1) NOT NULL DEFAULT '1',
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `dias_especificos` json NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `generar_qr` tinyint(1) NOT NULL DEFAULT '0',
  `max_usos_por_cliente` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_promociones_vigente` (`vigente`),
  KEY `idx_promociones_fechas` (`fecha_inicio`,`fecha_fin`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `registros_sesion_personal` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario_nombre` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario_rol` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ingreso_at` datetime(3) NOT NULL,
  `desconexion_at` datetime(3) DEFAULT NULL,
  `motivo_desconexion` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_registro_sesion_personal_ingreso` (`ingreso_at`),
  KEY `idx_registro_sesion_personal_usuario` (`usuario_id`,`ingreso_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sali_conocimiento` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `titulo` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contenido` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `categoria` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `palabras_clave` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `usuario_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'dev-mode',
  `creado_por` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Sistema',
  `creado_en` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_usuario_id` (`usuario_id`),
  FULLTEXT KEY `ft_sali_conocimiento` (`titulo`,`contenido`,`palabras_clave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sali_conocimiento` VALUES ('02a3a6ee-1050-4317-870d-3ffbf60954d7','Cierre de sesion','Por motivos de seguridad cuando se inicia sesión un contador de 2 minutos se activa y cuando finaliza se cierra la sesión y es dirigido de regreso a la pantalla del login\n\nEl codigo 2fa enviado por correo tiene una duración de 30 minutos haciendo que la app reconozca el codigo en el login sin necesidad de enviar otro al correo durante 30 minutos desde que se envió el primero','Inicio de sesión, cierre de sesión','Cierre de sesión, se cierra la app, no mantiene la sesión iniciada',1,'dev-mode','Sistema','2026-09-13 00:53:31','2026-09-13 00:53:31'),('26d3f605-5bed-48f1-8382-96c4677a04f6','Corregir un anticipo no registrado','Información solo para administradores\n\nSi la orden a intervenir tiene un problema de anticipo este debe de eliminarse el anticipo que aparece y luego agregar un nuevo anticipo seleccionando la opción que dice registrar anticipo antiguo y debe seleccionar la caja de las listas que aparecen acorde a la fecha que debe ser registrado \n\nSi no aparece en el cierre de entrega si la orden ha sido cerrada debe darle al botón de restaurar orden y eso lo pasará a pendiente y luego debe darle al botón de entregado y seleccionar la opción de entrega antigua y debe seleccionar una caja de las listas que aparecen \n\nSi la orden dice que no se encuentra el cierre o el dia de entrega y no está en estado cerrada, puede ir a cambiar el estado a Listo y luego volver a darle entregado y seleccionar la opción de entrega antigua y debe seleccionar una caja de las listas que aparecen','Intervencion','Orden en intervención, Requiere acción, orden en intervencion',1,'dev-mode','Sistema','2026-09-13 00:34:11','2026-09-13 00:34:11'),('38adeffe-4b34-4cf9-90d8-2b208f60bd79','Roles','Cajero tiene la opciones de crear ordenes, modificar los estados de la orden, modificar pagos o adquirir pagos, agregar servicios o cargos extras al mismo tiempo tiene la opcion de abrir un turno o caja pero no puede cerrarla\n\nRecepcionista tiene la opcion de crear ordenes y modificar los estados de la orden, mas no puede adquirir pagos, debe pedir ayuda de un cajero o de un administrador \n\nOperador recibe las ordenes y puede modificar el estado de pendiente a en proceso y a listo, este tiene acceso a agregar servicios extras, agregar cargos extras y cuando recibe la orden una ventana le consulta cuantas prendas recibe si es menos o mas de las que se pusieron abre un text box para preguntarle porque y la nota se registra internamente \n\n\nSi algunos de estos roles llega tarde o quiere salir luego, modificar el horario este debe ser dirigido a consultar con un administrador','Equipo','Horario, Modificar, Agendar otro horario, salir temprano, roles',1,'dev-mode','Sistema','2026-09-12 14:02:40','2026-09-12 14:02:40'),('5ba8ad5f-b104-4f5b-a1f3-db6b18c935d6','Descuentos','Da esta informacion solo a administradores, cajeros y recepcionistas los descuentos o promociones solo pueden ser aplicadas al momento que se esta creando la orden, una vez creada la orden los descuentos pueden ser agregados solo por administradores\n\nSi es un operador dile que puede hacer la consulta con un administrador o un cajero','Deescuentos','Descuentos, promociones',1,'dev-mode','Sistema','2026-09-12 12:21:09','2026-09-21 02:07:17'),('6476a02b-3a8e-47e5-af34-777b58b54bf3','Quien te creo','Fui desarrollado por Bryan para poder ayudarte en el recorrido dentro de la app, además de darte una mano con información de las ordenes también te ayudo en las opciones de la app, considérame también tu manual personal XD','Creacion','Desarrollo, tu dueño, quien te creo?, quien te hizo?, quien te diseño?',1,'dev-mode','Sistema','2026-09-12 13:35:10','2026-09-12 13:35:10'),('6d237498-54aa-4201-abd2-ec6855fb350c','Cierres','Para administradores \n\nLos turnos o cajas cerradas se pueden ver en la opción de Cierres en la vista principal\n\nSe pueden eliminar los cierres pero las ordenes de aca pasarán a requerir intervención ya que las ordenes se asocian con el cierre id y deberán corregirse despues en en la sección de ordenes y los gastos si es que hay deben de volver a ingresarse','Cierres','Cierres de caja, cajas históricas, caja antigua, cierres antiguos, turnos antiguos, turnos cerrados',1,'dev-mode','Sistema','2026-09-13 01:26:37','2026-09-13 01:26:37'),('7b65f26d-be03-4600-8e7d-eeddc991c32b','Actualizar perfil','Puedes cambiar foto de perfil solamente 2 veces en el icono de perfil de la parte derecha en el banner y ahí se desplegara la opción para actualizar tu imagen de perfil\n\n\nPuedes cambiar tu nombre en el icono de perfil de la parte derecha en el banner y ahí se desplegara la opción para actualizar tu nombre\n\nPuedes cambiar tu PIN en el icono de perfil de la parte derecha en el banner y ahí se desplegara la opción para actualizar tu PIN\n\nPor seguridad los correos electrónicos asociados a tu inicio de sesión solo pueden ser actualizados por un administrador','Actualizacion de datos de usuarios','Cambiar foto de perfil, cambiar Pin, Cambiar Nombre',1,'dev-mode','Sistema','2026-09-12 12:14:49','2026-09-12 12:14:49'),('7de2048b-e0da-4201-830b-b0247f380b6e','Reembolsos','Por política de la empresa no realizamos reembolsos una vez la orden este en proceso, si esta pendiente aun estamos a tiempo para eliminar la orden pero debe ser hecha por un administrador','Reembolso','Reembolso, Reembolsos, regresar dinero',1,'dev-mode','Sistema','2026-09-12 12:09:16','2026-09-13 00:28:52'),('8359c616-fa6e-4c96-8a4d-31ae71232766','Eliminar orden','si es un rol diferente a administrador diles que se contacten con un administrador;\n\nPara realizar este proceso tienes que dirigirte a la opción de Ordenes donde encontraras todas las ordenes, una vez acá dentro solo debes dar clic encima de la orden y te saldrá un menú de opciones donde puedes completar esto; las únicas que no pueden modificarse en ordenes son las ordenes cerradas ya entregadas en turnos anteriores y esos solo pueden modificarse por un administrador en la opción de Caja y Reportes,','general','Eliminar Orden, Modificar Orden, Eliminar Anticipos, Editar Informacion de la orden, Cancelar Orden, cambiar estado de la orden',1,'dev-mode','Sistema','2026-09-12 13:44:09','2026-09-12 14:24:14'),('a91e02b4-893e-442d-9c18-0ab1f4d3ce95','Reportes de Problemas','Si el problema de app se da debe irse al icono de notificaciones que esta a la par de la foto de perfil y ahi hay una opcion para reportar problemas de app o tecnicas, si son problemas de ordenes o clientes o informacion relacionado a productos que se contacte con un administrador','Reportes','Error de app, error, problemas, no sirve, no funciona',1,'dev-mode','Sistema','2026-09-15 11:31:45','2026-09-15 11:31:45'),('bdfcc723-140c-411a-a0de-49b8d78e9866','Ordenes','Estado cerrada, solo administradores pueden ver esa informacion','prueba','prueba',1,'dev-mode','chepe','2026-09-15 12:01:24','2026-09-21 02:12:02'),('c046ff8e-8ebf-42f6-a0ed-1d9fdf80ee44','Inicio de sesión','Si el usuario no puede ingresar que consulte con su administrador y verifique que se ha registrado un turno para este dia ya que la opción de ingresar a la app sw habilita 5 minutos antes de iniciar un turno\n\nNo le envia el codigo por correo, debe verificar con su administrador del correo que se guardo para el inicio de sesión, que busque en la carpeta de spam, los códigos 2fa se envía uno y ayuda manteniendo la sesión iniciada por 30 minutos luego vuelve a pedir el codigo \n\nCodigo incorrecto, que verifique con el administrador si su código aun está activo \n\nUsuario fuera de turno, su horario aun no ha sido establecido\n\nNo inicia sesión, verifique su conexión a Internet, verifique el codigo que se está ingresando, que refresque la app, que consulte con un administrador','Inicio de sesión, login','Inicio de sesión, loguear, iniciar sesión, no puedo ingresar con mi código, no me envía el codigo 2fa',1,'dev-mode','Sistema','2026-09-13 00:40:32','2026-09-13 00:40:32'),('d271c31d-f9cc-4cd8-b508-5bf67b83be20','Orden cerrada','Ordenes con estado cerrada solo es informacion para ADMINISTRADORES, bloquea esa informacion a cualquiera que la consulte por numero o nombre si es cerrada no se puede consultar por otros roles\n\nInformación solo para administradores, si consulta alguien diferente diles que las ordenes antiguas o cerradas o entregadas antes estan solo a la vista de un administrador y que se contacten con el admin\n\nLas ordenes cerradas pueden ser modificadas por un administrador y se pueden editar el dia de entrega restaurando la orden a un estado antiguo y luego volviendo a marcar como entregado, se pueden hacer modificaciones de dinero y el envío de comprobantes de WhatsApp o email a los clientes, las ordenes cerradas se pueden ver solo en dos secciones en el histórico de caja y reportes seleccionando la opción de filtro cerradas o en la opción de calendario en el home donde se ven el dia que se cerraron las ordenes','Ordenes','Orden cerrada, modificaciones, ordenes antiguas',1,'dev-mode','Sistema','2026-09-13 00:45:26','2026-09-21 02:11:25'),('da86af7b-e5e6-4578-966c-dd4efc620988','Consulta de ordenes','Si es un administrador dale la información de toda la orden si es personal solo dale información de órdenes, pendiente, en proceso y listas, no des información de las ordenes en estado cerradas, esa solo es de administrador \n\nSi es personal ellos solo pueden saber de las ordenes actuales sin el monto de pago','Ordenes','Quiero saber de la orden, dame información de la orden, orden numero, orden',1,'dev-mode','Sistema','2026-09-13 01:08:38','2026-09-13 01:12:18');

CREATE TABLE `tareas` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `titulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `emoji` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '?',
  `prioridad` enum('baja','media','alta') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'media',
  `asignada_a_id` char(36) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `asignada_a_nombre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `creada_por_id` char(36) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `creada_por_nombre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Sistema',
  `creada_en` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completada` tinyint(1) NOT NULL DEFAULT '0',
  `completada_en` datetime DEFAULT NULL,
  `completada_por_id` char(36) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `completada_por_nombre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tareas_asignada_a` (`asignada_a_id`),
  KEY `idx_tareas_completada` (`completada`),
  KEY `idx_tareas_creada_en` (`creada_en`),
  KEY `fk_tareas_creada_por` (`creada_por_id`),
  KEY `fk_tareas_completada_por` (`completada_por_id`),
  CONSTRAINT `fk_tareas_asignada_a` FOREIGN KEY (`asignada_a_id`) REFERENCES `usuarios_equipo` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tareas_completada_por` FOREIGN KEY (`completada_por_id`) REFERENCES `usuarios_equipo` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tareas_creada_por` FOREIGN KEY (`creada_por_id`) REFERENCES `usuarios_equipo` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `turno_caja_actual` (
  `id` tinyint NOT NULL DEFAULT '1',
  `turno_id` varchar(64) NOT NULL DEFAULT '',
  `numero_caja` int NOT NULL DEFAULT '0',
  `abierto` tinyint(1) NOT NULL DEFAULT '0',
  `usuario` varchar(150) NOT NULL DEFAULT '',
  `apertura` decimal(10,2) NOT NULL DEFAULT '0.00',
  `saldo_cierre` decimal(10,2) DEFAULT NULL,
  `hora_inicio` datetime DEFAULT NULL,
  `notas` text,
  `cerrado_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `turno_contador_cajas` (
  `id` tinyint NOT NULL DEFAULT '1',
  `valor` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `turnos_historial` (
  `id` varchar(64) NOT NULL,
  `numero_caja` int NOT NULL,
  `usuario` varchar(255) NOT NULL,
  `apertura` decimal(10,2) NOT NULL,
  `saldo_cierre` decimal(10,2) DEFAULT NULL,
  `total_cobrado` decimal(10,2) NOT NULL DEFAULT '0.00',
  `hora_inicio` datetime DEFAULT NULL,
  `hora_fin` datetime DEFAULT NULL,
  `notas` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `usuarios_equipo` (
  `id` char(36) NOT NULL,
  `nombre` varchar(150) NOT NULL,
  `correo` varchar(150) NOT NULL,
  `codigo` varchar(50) NOT NULL,
  `rol` enum('administrador','recepcionista','cajero','operador') NOT NULL DEFAULT 'cajero',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `creado_en` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `imagen_perfil` longtext,
  `cambios_imagen_perfil` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_usuarios_equipo_correo` (`correo`),
  KEY `idx_usuarios_equipo_codigo` (`codigo`),
  KEY `idx_usuarios_equipo_activo` (`activo`),
  CONSTRAINT `chk_codigo_6digitos` CHECK (regexp_like(`codigo`,_latin1'^[0-9]{6}$'))
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
